// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const REGIONS = {
  DE: { title: 'Germany', taxRate: 0.19 },
  FR: { title: 'France', taxRate: 0.2 },
  UK: { title: 'United Kingdom', taxRate: 0.2 },
};

const BULK_MIN_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER_MIN = 10000;
const NAME_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;

const round2 = (n) => Math.round(n * 100) / 100;

function groupThousands(digits, separator) {
  const groups = [];
  for (let end = digits.length; end > 0; end -= 3) {
    groups.unshift(digits.slice(Math.max(0, end - 3), end));
  }
  return groups.join(separator);
}

export function formatMoney(amount, region) {
  const sign = amount < 0 ? '-' : '';
  const [whole, cents] = Math.abs(amount).toFixed(2).split('.');
  switch (region) {
    case 'DE':
      return `${sign}${groupThousands(whole, '.')},${cents} €`;
    case 'FR':
      return `${sign}${groupThousands(whole, ' ')},${cents} €`;
    case 'UK':
      return `${sign}£${groupThousands(whole, ',')}.${cents}`;
    default:
      throw new Error('unknown region: ' + region);
  }
}

// Gross amount of one sale: discount, then bulk discount, then tax, rounded at each step.
function grossAmount(sale, taxRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net -= (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_MIN_UNITS) {
    net *= BULK_FACTOR;
  }
  net = round2(net);
  return round2(net + round2(net * taxRate));
}

function truncate(name) {
  return name.length > NAME_WIDTH ? name.slice(0, NAME_WIDTH - 1) + '…' : name;
}

function validateOptions(options) {
  if (options.format && options.format !== 'text') {
    throw new Error('unsupported format: ' + options.format);
  }
  if (options.month && !/^\d{4}-\d{2}$/.test(options.month)) {
    throw new Error('bad month: ' + options.month);
  }
}

export function buildReport(sales, options) {
  options = options || {};
  validateOptions(options);

  const lines = [options.month ? 'SALES REPORT ' + options.month : 'SALES REPORT', ''];

  let data = sales.slice();
  if (options.month) {
    data = data.filter((s) => s.date.slice(0, 7) === options.month);
  }
  data.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  let rows = 0;
  let largeOrders = 0;

  // Sections appear in this order; sales with units <= 0 or another region are left out.
  for (const [region, { title, taxRate }] of Object.entries(REGIONS)) {
    const regionSales = data.filter((s) => s.region === region && s.units > 0);
    if (regionSales.length === 0) continue;

    lines.push(`== ${title} ==`);
    let subtotal = 0;
    for (const sale of regionSales) {
      const amount = grossAmount(sale, taxRate);
      let line =
        truncate(sale.product).padEnd(NAME_WIDTH) +
        ' ' + String(sale.units).padStart(UNITS_WIDTH) +
        ' ' + formatMoney(amount, region).padStart(MONEY_WIDTH);
      if (amount >= LARGE_ORDER_MIN) {
        line += ' *';
        largeOrders++;
      }
      lines.push(line);
      subtotal += amount;
      rows++;
    }
    lines.push(`Subtotal ${region}: ${formatMoney(subtotal, region)}`, '');
  }

  if (rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + rows, 'Large orders: ' + largeOrders);
  }
  return lines.join('\n') + '\n';
}

